CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', max_hr integer NOT NULL DEFAULT 190 CHECK (max_hr BETWEEN 80 AND 240), resting_hr integer NOT NULL DEFAULT 50 CHECK (resting_hr BETWEEN 25 AND 120), ftp integer NOT NULL DEFAULT 250 CHECK (ftp BETWEEN 50 AND 600));
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (auth.uid()=id);
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (auth.uid()=id) WITH CHECK (auth.uid()=id);
CREATE FUNCTION public.create_athlete_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); RETURN NEW; END; $$;
CREATE TRIGGER create_athlete_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_athlete_profile();
CREATE TABLE public.garmin_connections (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, encrypted_key text NOT NULL, expires_at timestamptz, last_sync_at timestamptz, status text NOT NULL DEFAULT 'connected');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.garmin_connections TO service_role;
GRANT SELECT(user_id,expires_at,last_sync_at,status) ON public.garmin_connections TO authenticated;
ALTER TABLE public.garmin_connections ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_connection_status ON public.garmin_connections FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE TABLE public.activities (id text NOT NULL, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, sport text NOT NULL, started_at timestamptz NOT NULL, distance_m double precision NOT NULL DEFAULT 0, duration_s double precision NOT NULL DEFAULT 0, avg_hr double precision, avg_power double precision, elevation_m double precision, training_load double precision, PRIMARY KEY(user_id,id));
GRANT SELECT,INSERT,UPDATE ON public.activities TO authenticated;
GRANT ALL ON public.activities TO service_role;
ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_activities ON public.activities FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.wellness (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, day date NOT NULL, sleep_seconds double precision, resting_hr double precision, hrv double precision, stress double precision, PRIMARY KEY(user_id,day));
GRANT SELECT,INSERT,UPDATE ON public.wellness TO authenticated;
GRANT ALL ON public.wellness TO service_role;
ALTER TABLE public.wellness ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_wellness ON public.wellness FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);